CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'admin', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS database_targets (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name text NOT NULL, type text NOT NULL DEFAULT 'supabase', connection_encrypted text NOT NULL, ssl_mode text NOT NULL DEFAULT 'require', status text NOT NULL DEFAULT 'unknown', last_connection_test_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, name));
CREATE TABLE IF NOT EXISTS storage_destinations (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name text NOT NULL, provider text NOT NULL, endpoint text, region text, bucket text, prefix text NOT NULL DEFAULT 'vaultmanager', path text, credentials_encrypted text, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, name));
CREATE TABLE IF NOT EXISTS backup_jobs (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, database_target_id uuid NOT NULL REFERENCES database_targets(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT true, schedule text, timezone text NOT NULL DEFAULT 'UTC', backup_type text NOT NULL DEFAULT 'three_file', retention_count integer, retention_days integer, compression_enabled boolean NOT NULL DEFAULT true, verification_enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_run_at timestamptz, next_run_at timestamptz);
CREATE TABLE IF NOT EXISTS backup_runs (id uuid PRIMARY KEY, backup_job_id uuid REFERENCES backup_jobs(id) ON DELETE SET NULL, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, database_target_id uuid NOT NULL REFERENCES database_targets(id) ON DELETE CASCADE, status text NOT NULL, triggered_by text NOT NULL, started_at timestamptz, completed_at timestamptz, duration_ms bigint, exit_code integer, error_code text, error_message text, total_size_bytes bigint, checksum text, cli_version text, postgres_version text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS backup_artifacts (id uuid PRIMARY KEY, backup_run_id uuid NOT NULL REFERENCES backup_runs(id) ON DELETE CASCADE, artifact_type text NOT NULL, filename text NOT NULL, local_path text, size_bytes bigint, checksum text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS backup_storage_objects (id uuid PRIMARY KEY, backup_artifact_id uuid NOT NULL REFERENCES backup_artifacts(id) ON DELETE CASCADE, storage_destination_id uuid NOT NULL REFERENCES storage_destinations(id) ON DELETE CASCADE, object_key text NOT NULL, object_size bigint, checksum text, upload_status text NOT NULL DEFAULT 'pending', uploaded_at timestamptz, verified_at timestamptz, error_message text);
CREATE TABLE IF NOT EXISTS backup_logs (id bigserial PRIMARY KEY, backup_run_id uuid NOT NULL REFERENCES backup_runs(id) ON DELETE CASCADE, logged_at timestamptz NOT NULL DEFAULT now(), level text NOT NULL, phase text NOT NULL, message text NOT NULL, command text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS restore_jobs (id uuid PRIMARY KEY, backup_run_id uuid NOT NULL REFERENCES backup_runs(id), destination_target_id uuid NOT NULL REFERENCES database_targets(id), status text NOT NULL, started_at timestamptz, completed_at timestamptz, initiated_by text NOT NULL, confirmation_reference text, error_message text);
CREATE TABLE IF NOT EXISTS retention_policies (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name text NOT NULL, daily_count integer NOT NULL DEFAULT 7, weekly_count integer NOT NULL DEFAULT 4, monthly_count integer NOT NULL DEFAULT 12, retention_days integer, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, project_id uuid REFERENCES projects(id) ON DELETE SET NULL, actor text NOT NULL, action text NOT NULL, resource_type text, resource_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS backup_runs_status_idx ON backup_runs(status, created_at DESC);
CREATE INDEX IF NOT EXISTS backup_logs_run_idx ON backup_logs(backup_run_id, logged_at);
CREATE INDEX IF NOT EXISTS audit_logs_created_idx ON audit_logs(created_at DESC);
